using System.Security.Cryptography;using System.Text;namespace QuantForge.Core;public sealed record AndroidDatasetSelection(string SelectionFingerprint,string DatasetId,string DatasetFingerprint,string Instrument,string Timeframe);public static class AndroidDatasetSelectionRules{public static AndroidDatasetSelection Create(DatasetCatalogEntry entry){if(!entry.StructurallyValidated||string.IsNullOrWhiteSpace(entry.DatasetFingerprint))throw new InvalidOperationException("Android dataset selection requires admitted structural evidence.");var text=string.Join("|",entry.DatasetId,entry.DatasetFingerprint,entry.Instrument,entry.Timeframe);var fp=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));return new(fp,entry.DatasetId,entry.DatasetFingerprint,entry.Instrument,entry.Timeframe);}public static void Validate(AndroidDatasetSelection value,DatasetCatalogEntry entry){if(Create(entry)!=value)throw new InvalidOperationException("Android dataset selection does not match catalog evidence.");}}
